//! The Arlington PDF Model as static tables, generated by `build.rs`.

/// Index into [`TYPES`].
pub type TypeId = u16;

/// PDF version as `major * 10 + minor` (17 = PDF 1.7); 0 = unspecified.
pub type Ver = u8;

/// Arlington's basic types.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Base {
    Array,
    Bitmask,
    Boolean,
    Date,
    Dictionary,
    Integer,
    Matrix,
    Name,
    NameTree,
    Null,
    Number,
    NumberTree,
    Rectangle,
    Stream,
    String,
    StringAscii,
    StringByte,
    StringText,
}

impl Base {
    pub fn as_str(self) -> &'static str {
        match self {
            Base::Array => "array",
            Base::Bitmask => "bitmask",
            Base::Boolean => "boolean",
            Base::Date => "date",
            Base::Dictionary => "dictionary",
            Base::Integer => "integer",
            Base::Matrix => "matrix",
            Base::Name => "name",
            Base::NameTree => "name-tree",
            Base::Null => "null",
            Base::Number => "number",
            Base::NumberTree => "number-tree",
            Base::Rectangle => "rectangle",
            Base::Stream => "stream",
            Base::String => "string",
            Base::StringAscii => "string-ascii",
            Base::StringByte => "string-byte",
            Base::StringText => "string-text",
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub enum Req {
    No,
    Yes,
    /// Required when the expression holds (`fn:IsRequired(...)`).
    Cond(&'static str),
}

#[derive(Clone, Copy, Debug)]
pub enum Indirect {
    Any,
    Must,
    MustNot,
    MustIf(&'static str),
    MustNotIf(&'static str),
}

#[derive(Clone, Copy, Debug)]
pub enum Lit {
    Name(&'static str),
    Int(i64),
    Num(f64),
    Str(&'static str),
    Bool(bool),
}

#[derive(Clone, Copy, Debug)]
pub struct LitDef {
    pub lit: Lit,
    pub since: Ver,
    pub deprecated: Ver,
}

/// `PossibleValues`: a value is allowed when it equals one of `lits` or
/// satisfies one of `evals`. `open` means some alternative is not checked
/// (wildcards, unsupported predicates).
#[derive(Clone, Copy, Debug)]
pub struct Values {
    pub lits: &'static [LitDef],
    pub evals: &'static [&'static str],
    pub open: bool,
}

#[derive(Clone, Copy, Debug)]
pub struct Link {
    pub ty: TypeId,
    pub since: Ver,
    /// Only valid in this version (`fn:IsPDFVersion`).
    pub only: Ver,
}

/// One alternative type of a key.
#[derive(Clone, Copy, Debug)]
pub struct Slot {
    pub base: Base,
    pub since: Ver,
    pub deprecated: Ver,
    pub indirect: Indirect,
    pub values: Option<Values>,
    pub links: &'static [Link],
}

#[derive(Clone, Copy, Debug)]
pub struct KeyDef {
    /// Dictionary key, array index (`0`), wildcard (`*`) or repeating array
    /// element (`1*`).
    pub key: &'static str,
    pub slots: &'static [Slot],
    pub since: Ver,
    /// Extension that defines the key, if any.
    pub extension: &'static str,
    pub deprecated: Ver,
    pub required: Req,
    pub inheritable: bool,
    pub default: &'static str,
    pub note: &'static str,
}

#[derive(Debug)]
pub struct TypeDef {
    pub name: &'static str,
    pub array: bool,
    pub keys: &'static [KeyDef],
}

include!(concat!(env!("OUT_DIR"), "/arlington.rs"));
